def decode(s: str) -> str:
    out, i = [], 0
    while i < len(s):
        ch = s[i]
        j = i + 1
        while j < len(s) and s[j].isdigit():
            j += 1
        out.append(ch * int(s[i+1:j]))
        i = j
    return ''.join(out)
