class HashMap:
    def __init__(self, size=64):
        self.size = size
        self.buckets = [[] for _ in range(size)]

    def _idx(self, key):
        return hash(key) % self.size

    def put(self, key, value):
        b = self.buckets[self._idx(key)]
        for i, (k, _) in enumerate(b):
            if k == key:
                b[i] = (key, value); return
        b.append((key, value))

